@Slf4j
@PluginDescriptor(
	name = "Clan Piano Tutor",
	description = "Highlights the next key to play on the Clan Hall piano, with a songbook of famous tunes",
	tags = {"piano", "clan", "hall", "music", "song", "notes"},
	internalName = "clan-piano-tutor",
	// Songs used to live in .runelite/clan-piano-songs; RuneLite moves them to plugin-data.
	legacyDataDirectory = "clan-piano-songs"
)
public class ClanPianoPlugin extends Plugin
{
	private static final String LAST_SONG_KEY = "lastSong";
	private static final String FAVOURITES_KEY = "favourites";
	private static final String MELODY_KEY_PREFIX = "melody_";
	private static final long WRONG_FLASH_MS = 400;
	private static final long HIT_BLINK_MS = 180;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClanPianoConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private KeyManager keyManager;

	@Inject
	private PianoKeyOverlay keyOverlay;

	@Inject
	private SongInfoOverlay infoOverlay;

	@Inject
	private TimingLaneOverlay laneOverlay;

	@Getter
	private final SongPlayer player = new SongPlayer();

	/** Built-in songs plus the player's own, from .runelite/plugin-data/clan-piano-tutor. */
	@Getter
	private SongLibrary library = new SongLibrary(null);

	@Getter
	private PianoKey wrongKey;
	private long wrongAt;
	private long hitAt;
	private long lastTickNanos;

	private final Set<String> favourites = Collections.synchronizedSet(new LinkedHashSet<>());
	private ClanPianoPanel panel;
	private NavigationButton navButton;

	private final KeyListener keyListener = new KeyListener()
	{
		@Override
		public void keyTyped(KeyEvent e)
		{
		}

		@Override
		public void keyPressed(KeyEvent e)
		{
			int code = e.getKeyCode();
			char ch = e.getKeyChar();
			clientThread.invoke(() ->
			{
				if (isPianoOpen())
				{
					log.debug("PIANO-DIAG key tick={} code={} ({}) char='{}'", client.getTickCount(), code, KeyEvent.getKeyText(code), ch);
				}
				if (config.keyboardInput() && ch != KeyEvent.CHAR_UNDEFINED)
				{
					onTyped(String.valueOf(ch));
				}
			});
		}

		@Override
		public void keyReleased(KeyEvent e)
		{
		}
	};

	@Provides
	ClanPianoConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ClanPianoConfig.class);
	}

	/** The player's song folder, or null (built-in songs only) if RuneLite can't provide one. */
	private Filepath songFolder()
	{
		try
		{
			return getPluginDirectory();
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("No song folder: only the built-in songs are available", e);
			return null;
		}
	}

	@Override
	protected void startUp()
	{
		library = new SongLibrary(songFolder());
		library.reload();
		favourites.clear();
		String favs = configManager.getConfiguration(ClanPianoConfig.GROUP, FAVOURITES_KEY);
		if (favs != null && !favs.isEmpty())
		{
			favourites.addAll(Arrays.asList(favs.split(Pattern.quote("|"))));
		}
		panel = new ClanPianoPanel(this);
		navButton = NavigationButton.builder()
			.tooltip("Clan Piano Tutor")
			.icon(createIcon())
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		overlayManager.add(keyOverlay);
		overlayManager.add(infoOverlay);
		overlayManager.add(laneOverlay);
		keyManager.registerKeyListener(keyListener);

		String last = configManager.getConfiguration(ClanPianoConfig.GROUP, LAST_SONG_KEY);
		Song initial = library.getSongs().stream()
			.filter(s -> s.id().equals(last) || s.getTitle().equals(last))
			.findFirst()
			.orElse(library.getSongs().isEmpty() ? null : library.getSongs().get(0));
		player.load(resolveVersion(initial));
		panel.setSongs(library.getSongs(), library.getFolders(), initial, library.getErrors());
		panel.setMode(config.mode());
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(keyListener);
		overlayManager.remove(keyOverlay);
		overlayManager.remove(infoOverlay);
		overlayManager.remove(laneOverlay);
		clientToolbar.removeNavigation(navButton);
		player.stop();
		panel = null;
		navButton = null;
	}

	// ---- Called from the side panel (Swing thread); state changes happen on the client thread ----

	void selectSong(Song song)
	{
		clientThread.invoke(() ->
		{
			boolean wasPlaying = player.isActive();
			player.load(resolveVersion(song));
			if (wasPlaying && song != null)
			{
				// Switching songs mid-play goes straight into the new one.
				player.start(config.mode(), config.countIn(), config.loop(), config.leadTicks());
			}
			if (song != null)
			{
				configManager.setConfiguration(ClanPianoConfig.GROUP, LAST_SONG_KEY, song.id());
			}
			refreshPanel();
		});
	}

	void setMode(PlayMode mode)
	{
		clientThread.invoke(() ->
		{
			configManager.setConfiguration(ClanPianoConfig.GROUP, ClanPianoConfig.MODE_KEY, mode);
			player.stop();
			refreshPanel();
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (ClanPianoConfig.GROUP.equals(event.getGroup()) && ClanPianoConfig.MODE_KEY.equals(event.getKey()))
		{
			PlayMode mode = config.mode();
			SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.setMode(mode);
				}
			});
		}
	}

	void startSong()
	{
		clientThread.invoke(() ->
		{
			player.start(config.mode(), config.countIn(), config.loop(), config.leadTicks());
			refreshPanel();
		});
	}

	void stopSong()
	{
		clientThread.invoke(() ->
		{
			player.stop();
			refreshPanel();
		});
	}

	void reloadSongs()
	{
		clientThread.invoke(() ->
		{
			Song selected = player.getSong();
			library.reload();
			List<Song> songs = library.getSongs();
			Song match = selected == null ? null : songs.stream()
				.filter(s -> s.id().equals(selected.id()))
				.findFirst().orElse(null);
			if (match == null && !songs.isEmpty())
			{
				match = songs.get(0);
			}
			player.load(resolveVersion(match));
			Song finalMatch = match;
			List<String> folders = library.getFolders();
			SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.setSongs(songs, folders, finalMatch, library.getErrors());
				}
			});
		});
	}

	// ---- Game events ----

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		lastTickNanos = System.nanoTime();
		if (player.getMode() == PlayMode.TEMPO && player.isActive())
		{
			player.tick();
			refreshPanel();
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() != InterfaceID.CLAN_PIANO)
		{
			return;
		}
		// Log where the game puts each key and label once the interface has laid out,
		// so highlight positions can be checked against what is on screen.
		clientThread.invokeLater(() ->
		{
			StringBuilder sb = new StringBuilder("Clan piano layout:");
			for (PianoKey key : PianoKey.values())
			{
				sb.append("\n  ").append(key.name())
					.append(" key=").append(describe(client.getWidget(key.getWidgetId())))
					.append(" label=").append(describe(client.getWidget(key.getLabelWidgetId())))
					.append(" box=").append(keyOverlay.bounds(key));
			}
			log.debug(sb.toString());
		});
	}

	private static String describe(Widget w)
	{
		if (w == null)
		{
			return "null";
		}
		return "type" + w.getType() + (w.isHidden() ? " hidden " : " ") + w.getBounds()
			+ (w.getText() == null || w.getText().isEmpty() ? "" : " '" + w.getText() + "'");
	}

	@Subscribe
	public void onSoundEffectPlayed(SoundEffectPlayed event)
	{
		if (isPianoOpen())
		{
			log.debug("PIANO-DIAG sound tick={} id={} delay={} source={}", client.getTickCount(), event.getSoundId(), event.getDelay(),
				event.getSource() == null ? "none" : event.getSource().getName());
		}
	}

	@Subscribe
	public void onAreaSoundEffectPlayed(AreaSoundEffectPlayed event)
	{
		if (isPianoOpen())
		{
			log.debug("PIANO-DIAG areasound tick={} id={} delay={} at={},{} source={}", client.getTickCount(), event.getSoundId(),
				event.getDelay(), event.getSceneX(), event.getSceneY(),
				event.getSource() == null ? "none" : event.getSource().getName());
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (isPianoOpen())
		{
			Widget w = event.getWidget();
			log.debug("PIANO-DIAG click tick={} option='{}' target='{}' action={} id={} p0={} p1={} widget={} item={}",
				client.getTickCount(), event.getMenuOption(), event.getMenuTarget(), event.getMenuAction(), event.getId(),
				event.getParam0(), event.getParam1(), w == null ? "null" : Integer.toHexString(w.getId()) + "[" + w.getIndex() + "]",
				event.getItemId());
		}
		PianoKey key = PianoKey.fromWidgetId(event.getParam1());
		if (key == null)
		{
			Widget widget = event.getWidget();
			key = widget == null ? null : PianoKey.fromWidgetId(widget.getId());
		}
		if (key != null)
		{
			onKeyPlayed(key);
		}
	}

	private void onTyped(String typed)
	{
		if (!isPianoOpen())
		{
			return;
		}
		for (PianoKey key : PianoKey.values())
		{
			Widget label = client.getWidget(key.getLabelWidgetId());
			if (label != null && !label.isHidden() && typed.equalsIgnoreCase(Text.removeTags(label.getText()).trim()))
			{
				onKeyPlayed(key);
				return;
			}
		}
	}

	private void onKeyPlayed(PianoKey key)
	{
		// No need to press Start: playing the song's first note starts it (after picking a
		// song, or after finishing one). Other keys are left alone so noodling doesn't.
		SongPlayer.State state = player.getState();
		if (state == SongPlayer.State.IDLE || state == SongPlayer.State.FINISHED)
		{
			Step first = player.firstNote();
			if (first == null || !first.getKeys().contains(key))
			{
				return;
			}
			player.startAtFirstNote(config.mode(), config.loop(), config.leadTicks());
		}
		SongPlayer.PressResult result = player.press(key);
		log.debug("PIANO-PRESS {} -> {} (step {}, now {})", key, result, player.getPosition(), player.current());
		if (result == SongPlayer.PressResult.HIT || result == SongPlayer.PressResult.WRONG)
		{
			hitAt = System.currentTimeMillis();
		}
		if (result == SongPlayer.PressResult.WRONG)
		{
			wrongKey = key;
			wrongAt = System.currentTimeMillis();
		}
		if (result != SongPlayer.PressResult.IGNORED)
		{
			refreshPanel();
		}
	}

	// ---- Melody versions of MIDI songs (called from the panel) ----

	/** The melody version the player picked for this song last time, else the best guess. */
	Song resolveVersion(Song song)
	{
		if (song == null || song.getAlternatives().isEmpty())
		{
			return song;
		}
		String part = configManager.getConfiguration(ClanPianoConfig.GROUP, melodyKey(song));
		return song.versions().stream().filter(v -> v.getPart().equals(part)).findFirst().orElse(song);
	}

	void selectVersion(Song song, Song version)
	{
		clientThread.invoke(() ->
		{
			configManager.setConfiguration(ClanPianoConfig.GROUP, melodyKey(song), version.getPart());
			player.load(version);
			refreshPanel();
		});
	}

	private static String melodyKey(Song song)
	{
		return MELODY_KEY_PREFIX + song.id().replaceAll("[^A-Za-z0-9]", "_");
	}

	// ---- Favourites (called from the panel) ----

	boolean isFavourite(Song song)
	{
		return song != null && favourites.contains(song.id());
	}

	void toggleFavourite(Song song)
	{
		if (song == null)
		{
			return;
		}
		if (!favourites.remove(song.id()))
		{
			favourites.add(song.id());
		}
		String joined;
		synchronized (favourites)
		{
			joined = String.join("|", favourites);
		}
		configManager.setConfiguration(ClanPianoConfig.GROUP, FAVOURITES_KEY, joined);
	}

	// ---- Helpers for overlays ----

	boolean isPianoOpen()
	{
		Widget keys = client.getWidget(InterfaceID.ClanPiano.KEYS);
		return keys != null && !keys.isHidden();
	}

	/**
	 * How far through the current game tick we are, 0 to 1, so the falling notes can move
	 * smoothly between ticks. 0 when the song is not running to the clock.
	 */
	double tickProgress()
	{
		if (player.getMode() != PlayMode.TEMPO || !player.isActive() || lastTickNanos == 0)
		{
			return 0;
		}
		double p = (System.nanoTime() - lastTickNanos) / 600_000_000.0;
		return Math.max(0, Math.min(1, p));
	}

	/** True just after a correct press, so the box can blink and a repeated note is visible. */
	boolean inHitBlink()
	{
		return System.currentTimeMillis() - hitAt < HIT_BLINK_MS;
	}

	PianoKey activeWrongKey()
	{
		if (wrongKey != null && System.currentTimeMillis() - wrongAt > WRONG_FLASH_MS)
		{
			wrongKey = null;
		}
		return wrongKey;
	}

	private void refreshPanel()
	{
		SongPlayer.State state = player.getState();
		Song song = player.getSong();
		int position = player.getPosition();
		int hits = player.getHits();
		int misses = player.getMisses();
		int wrong = player.getWrong();
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.updateStatus(state, song, position, hits, misses, wrong);
			}
		});
	}

	private static BufferedImage createIcon()
	{
		BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setColor(new Color(240, 240, 240));
		g.fillRect(1, 3, 14, 10);
		g.setColor(new Color(40, 40, 40));
		g.drawRect(1, 3, 14, 10);
		for (int x = 4; x < 15; x += 3)
		{
			g.drawLine(x, 3, x, 13);
		}
		g.setColor(new Color(20, 20, 20));
		for (int x : new int[]{3, 6, 12})
		{
			g.fillRect(x, 3, 2, 6);
		}
		g.dispose();
		return img;
	}
}

package com.clanpiano;

import lombok.Getter;
import net.runelite.api.gameval.InterfaceID;

/**
 * The 24 keys of the Clan Hall piano, C4 to B5, in pitch order.
 * The game names the octaves 1 and 2; musically they are octaves 4 and 5.
 */
@Getter
public enum PianoKey
{
	C4("C", 4, false, InterfaceID.ClanPiano.KEY_C1, InterfaceID.ClanPiano.LABEL_C1),
	CS4("C#", 4, true, InterfaceID.ClanPiano.KEY_CSHARP1, InterfaceID.ClanPiano.LABEL_CSHARP1),
	D4("D", 4, false, InterfaceID.ClanPiano.KEY_D1, InterfaceID.ClanPiano.LABEL_D1),
	DS4("D#", 4, true, InterfaceID.ClanPiano.KEY_DSHARP1, InterfaceID.ClanPiano.LABEL_DSHARP1),
	E4("E", 4, false, InterfaceID.ClanPiano.KEY_E1, InterfaceID.ClanPiano.LABEL_E1),
	F4("F", 4, false, InterfaceID.ClanPiano.KEY_F1, InterfaceID.ClanPiano.LABEL_F1),
	FS4("F#", 4, true, InterfaceID.ClanPiano.KEY_FSHARP1, InterfaceID.ClanPiano.LABEL_FSHARP1),
	G4("G", 4, false, InterfaceID.ClanPiano.KEY_G1, InterfaceID.ClanPiano.LABEL_G1),
	GS4("G#", 4, true, InterfaceID.ClanPiano.KEY_GSHARP1, InterfaceID.ClanPiano.LABEL_GSHARP1),
	A4("A", 4, false, InterfaceID.ClanPiano.KEY_A1, InterfaceID.ClanPiano.LABEL_A1),
	AS4("A#", 4, true, InterfaceID.ClanPiano.KEY_ASHARP1, InterfaceID.ClanPiano.LABEL_ASHARP1),
	B4("B", 4, false, InterfaceID.ClanPiano.KEY_B1, InterfaceID.ClanPiano.LABEL_B1),
	C5("C", 5, false, InterfaceID.ClanPiano.KEY_C2, InterfaceID.ClanPiano.LABEL_C2),
	CS5("C#", 5, true, InterfaceID.ClanPiano.KEY_CSHARP2, InterfaceID.ClanPiano.LABEL_CSHARP2),
	D5("D", 5, false, InterfaceID.ClanPiano.KEY_D2, InterfaceID.ClanPiano.LABEL_D2),
	DS5("D#", 5, true, InterfaceID.ClanPiano.KEY_DSHARP2, InterfaceID.ClanPiano.LABEL_DSHARP2),
	E5("E", 5, false, InterfaceID.ClanPiano.KEY_E2, InterfaceID.ClanPiano.LABEL_E2),
	F5("F", 5, false, InterfaceID.ClanPiano.KEY_F2, InterfaceID.ClanPiano.LABEL_F2),
	FS5("F#", 5, true, InterfaceID.ClanPiano.KEY_FSHARP2, InterfaceID.ClanPiano.LABEL_FSHARP2),
	G5("G", 5, false, InterfaceID.ClanPiano.KEY_G2, InterfaceID.ClanPiano.LABEL_G2),
	GS5("G#", 5, true, InterfaceID.ClanPiano.KEY_GSHARP2, InterfaceID.ClanPiano.LABEL_GSHARP2),
	A5("A", 5, false, InterfaceID.ClanPiano.KEY_A2, InterfaceID.ClanPiano.LABEL_A2),
	AS5("A#", 5, true, InterfaceID.ClanPiano.KEY_ASHARP2, InterfaceID.ClanPiano.LABEL_ASHARP2),
	B5("B", 5, false, InterfaceID.ClanPiano.KEY_B2, InterfaceID.ClanPiano.LABEL_B2);

	public static final int LOWEST_MIDI = 60; // C4
	private static final PianoKey[] VALUES = values();

	private final String pitchClass;
	private final int octave;
	private final boolean black;
	private final int widgetId;
	private final int labelWidgetId;

	PianoKey(String pitchClass, int octave, boolean black, int widgetId, int labelWidgetId)
	{
		this.pitchClass = pitchClass;
		this.octave = octave;
		this.black = black;
		this.widgetId = widgetId;
		this.labelWidgetId = labelWidgetId;
	}

	/** Position on the keyboard, 0 (C4) to 23 (B5). */
	public int index()
	{
		return ordinal();
	}

	/**
	 * The name as printed on the piano ("C", "F#"), with ' added for the right-hand
	 * (higher) octave, since the piano prints the same letters for both halves.
	 */
	public String displayName()
	{
		return octave == 5 ? pitchClass + "'" : pitchClass;
	}

	public static PianoKey fromIndex(int index)
	{
		return index >= 0 && index < VALUES.length ? VALUES[index] : null;
	}

	public static PianoKey fromMidi(int midi)
	{
		return fromIndex(midi - LOWEST_MIDI);
	}

	/**
	 * The key a clicked widget belongs to. In game the click lands on the key's letter
	 * label (menu option "Play-g" on LABEL_G1), which covers the key; the 3D key model
	 * itself is not clickable. The model id is accepted too, just in case.
	 */
	public static PianoKey fromWidgetId(int widgetId)
	{
		for (PianoKey key : VALUES)
		{
			if (key.labelWidgetId == widgetId || key.widgetId == widgetId)
			{
				return key;
			}
		}
		return null;
	}
}

package com.clanpiano;

import com.clanpiano.song.Step;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Paints boxes straight onto the piano: the key(s) to play now, the next key(s), and wrong presses.
 *
 * Boxes are placed from the note letters the piano prints (white-key letters under the keys,
 * sharps above them), because those sit exactly where the drawn keys are. The key widgets'
 * own bounds are only a fallback.
 */
class PianoKeyOverlay extends Overlay
{
	private final Client client;
	private final ClanPianoPlugin plugin;
	private final ClanPianoConfig config;

	@Inject
	PianoKeyOverlay(Client client, ClanPianoPlugin plugin, ClanPianoConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!plugin.isPianoOpen())
		{
			return null;
		}
		SongPlayer player = plugin.getPlayer();

		if (player.getState() == SongPlayer.State.IDLE || player.getState() == SongPlayer.State.FINISHED)
		{
			// Not started (or done): light the first note, which starts the song when played.
			Step first = player.firstNote();
			if (first != null)
			{
				first.getKeys().forEach(k -> fill(g, k, config.currentColor()));
			}
			return null;
		}

		if (config.showNextKey())
		{
			List<Step> upcoming = player.upcoming(8);
			Step next = upcoming.stream().filter(s -> !s.isRest()).findFirst().orElse(null);
			if (next != null)
			{
				for (PianoKey key : next.getKeys())
				{
					outline(g, key, config.nextColor());
				}
			}
		}

		Set<PianoKey> now = plugin.inHitBlink() ? Set.of() : player.remaining();
		for (PianoKey key : now)
		{
			fill(g, key, config.currentColor());
		}

		PianoKey wrong = config.showWrongKey() ? plugin.activeWrongKey() : null;
		if (wrong != null)
		{
			fill(g, wrong, config.wrongColor());
		}
		return null;
	}

	Rectangle bounds(PianoKey key)
	{
		Rectangle r = labelBox(key);
		return r != null ? r : widgetBox(key);
	}

	/** Box worked out from the printed note letters. */
	private Rectangle labelBox(PianoKey key)
	{
		Rectangle lowC = labelBounds(PianoKey.C4);
		Rectangle highB = labelBounds(PianoKey.B5);
		Rectangle sharp = labelBounds(PianoKey.CS4);
		Rectangle mine = labelBounds(key);
		if (lowC == null || highB == null || sharp == null || mine == null)
		{
			return null;
		}

		// The label widgets are tall boxes that overlap the keys: the sharp letters sit at the
		// top of theirs and the white-key letters at the bottom of theirs. These proportions
		// were measured against the piano as drawn in game.
		double whiteWidth = (centerX(highB) - centerX(lowC)) / 13.0;
		double top = sharp.y + sharp.height * 0.48;     // top edge of the keys
		double bottom = lowC.y + lowC.height * 0.72;    // bottom edge of the white keys
		double height = bottom - top;
		if (whiteWidth < 6 || height < 12)
		{
			return null;
		}

		int cx = centerX(mine);
		if (key.isBlack())
		{
			int w = (int) Math.round(whiteWidth * 0.6);
			int h = (int) Math.round(height * 0.56);
			return new Rectangle(cx - w / 2, (int) Math.round(top), w, h);
		}
		// White keys: the part below the black keys, so the box never hides a black key.
		int w = (int) Math.round(whiteWidth * 0.8);
		int y = (int) Math.round(top + height * 0.6);
		return new Rectangle(cx - w / 2, y, w, (int) Math.round(bottom) - y);
	}

	private Rectangle widgetBox(PianoKey key)
	{
		Widget w = client.getWidget(key.getWidgetId());
		if (w == null || w.isHidden())
		{
			return null;
		}
		Rectangle r = w.getBounds();
		if (r == null || r.width <= 2 || r.height <= 2)
		{
			return null;
		}
		return new Rectangle(r.x + 1, r.y + 1, r.width - 2, r.height - 2);
	}

	private Rectangle labelBounds(PianoKey key)
	{
		Widget w = client.getWidget(key.getLabelWidgetId());
		if (w == null || w.isHidden())
		{
			return null;
		}
		Rectangle r = w.getBounds();
		return r == null || r.width <= 0 || r.height <= 0 ? null : r;
	}

	private static int centerX(Rectangle r)
	{
		return r.x + r.width / 2;
	}

	private void fill(Graphics2D g, PianoKey key, Color color)
	{
		Rectangle r = bounds(key);
		if (r == null)
		{
			return;
		}
		g.setColor(color);
		g.fill(r);
		g.setColor(color.darker());
		g.setStroke(new BasicStroke(2));
		g.draw(r);
	}

	private void outline(Graphics2D g, PianoKey key, Color color)
	{
		Rectangle r = bounds(key);
		if (r == null)
		{
			return;
		}
		g.setColor(color);
		g.setStroke(new BasicStroke(3));
		g.draw(r);
	}
}

