package com.clanpiano;

import com.clanpiano.song.Song;
import com.clanpiano.song.Step;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import java.util.stream.Collectors;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/** A small box with the song name, progress, the note to play now and the notes after it. */
class SongInfoOverlay extends OverlayPanel
{
	private final ClanPianoPlugin plugin;
	private final ClanPianoConfig config;

	@Inject
	SongInfoOverlay(ClanPianoPlugin plugin, ClanPianoConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(220, 0));
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		SongPlayer player = plugin.getPlayer();
		Song song = player.getSong();
		if (!config.showInfoBox() || song == null || !plugin.isPianoOpen())
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder().text(song.getTitle()).color(Color.ORANGE).build());

		switch (player.getState())
		{
			case IDLE:
				line("Click the green key to start", "", Color.GREEN, Color.GREEN);
				break;
			case COUNT_IN:
				line("Get ready", String.valueOf(player.getCountIn()), Color.YELLOW);
				line("First", upcomingText(player.upcoming(config.upcomingCount())));
				break;
			case PLAYING:
				Step now = player.current();
				line("Play", now == null || now.isRest() ? "(rest)" : now.label(), Color.GREEN);
				line("Then", upcomingText(player.upcoming(config.upcomingCount())));
				line("Progress", (player.getPosition() + 1) + " / " + song.length());
				if (player.getMode() == PlayMode.TEMPO)
				{
					line("Hit / missed", player.getHits() + " / " + player.getMisses());
				}
				line("' = right half of the piano", "", Color.GRAY, Color.GRAY);
				break;
			case FINISHED:
				line("Finished!", "", Color.GREEN);
				line("Notes hit", player.getHits() + " / " + song.noteCount());
				line("Wrong keys", String.valueOf(player.getWrong()));
				break;
		}
		return super.render(g);
	}

	private static String upcomingText(List<Step> steps)
	{
		return steps.stream().map(Step::label).collect(Collectors.joining(" "));
	}

	private void line(String left, String right)
	{
		line(left, right, Color.WHITE);
	}

	private void line(String left, String right, Color rightColor)
	{
		line(left, right, Color.WHITE, rightColor);
	}

	private void line(String left, String right, Color leftColor, Color rightColor)
	{
		panelComponent.getChildren().add(LineComponent.builder()
			.left(left)
			.leftColor(leftColor)
			.right(right)
			.rightColor(rightColor)
			.build());
	}
}

package com.clanpiano;

import com.clanpiano.song.Song;
import com.clanpiano.song.Step;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;
import lombok.Getter;

/**
 * Tracks where the player is in a song. Holds no RuneLite state so it can be unit tested.
 *
 * <ul>
 * <li>{@link PlayMode#FOLLOW}: waits for a press, then moves on, even after a wrong key.
 * Rests are skipped.</li>
 * <li>{@link PlayMode#TEMPO}: the song moves one step every game tick, the timing the hall
 * hears. {@code position} is the step whose tick it is now; {@code cursor} is the next note
 * still to be played. A note opens for pressing {@code lead} ticks before its own tick, so its
 * key can light up early and there is time to click it. Once pressed (right or wrong) the
 * next note opens as soon as it is inside its lead window. A note whose tick ends before it
 * was played is a miss.</li>
 * </ul>
 */
public class SongPlayer
{
	public enum State
	{
		IDLE,
		COUNT_IN,
		PLAYING,
		FINISHED
	}

	public enum PressResult
	{
		/** Nothing is playing, or nothing is open yet. */
		IGNORED,
		/** Right key; the note is complete. */
		HIT,
		/** Right key, but other keys of the chord are still needed. */
		PARTIAL,
		/** A key that is not the note to play. */
		WRONG
	}

	@Getter
	private Song song;
	@Getter
	private PlayMode mode = PlayMode.FOLLOW;
	@Getter
	private State state = State.IDLE;
	/** The step that is due on this tick (tempo), or the step being waited for (follow). */
	@Getter
	private int position;
	/** The next note still to be played. */
	@Getter
	private int cursor;
	@Getter
	private int countIn;
	@Getter
	private int lead;
	@Getter
	private int hits;
	@Getter
	private int misses;
	@Getter
	private int wrong;

	private boolean loop;
	private final Set<PianoKey> pressed = EnumSet.noneOf(PianoKey.class);

	public void load(Song song)
	{
		this.song = song;
		stop();
	}

	public void start(PlayMode mode, int countInTicks, boolean loop)
	{
		start(mode, countInTicks, loop, 0);
	}

	public void start(PlayMode mode, int countInTicks, boolean loop, int leadTicks)
	{
		if (song == null)
		{
			return;
		}
		reset(mode, loop, leadTicks);
		if (mode == PlayMode.TEMPO && countInTicks > 0)
		{
			countIn = countInTicks;
			state = State.COUNT_IN;
			cursor = firstNoteFrom(0);
		}
		else
		{
			state = State.PLAYING;
			if (mode == PlayMode.FOLLOW)
			{
				position = firstNoteFrom(0);
			}
			cursor = firstNoteFrom(position);
		}
	}

	public void startAtFirstNote(PlayMode mode, boolean loop)
	{
		startAtFirstNote(mode, loop, 0);
	}

	/** Starts right on the first note, with no count-in: used when the player just plays it. */
	public void startAtFirstNote(PlayMode mode, boolean loop, int leadTicks)
	{
		if (song == null)
		{
			return;
		}
		reset(mode, loop, leadTicks);
		state = State.PLAYING;
		position = firstNoteFrom(0);
		cursor = position;
	}

	private void reset(PlayMode mode, boolean loop, int leadTicks)
	{
		this.mode = mode;
		this.loop = loop;
		this.lead = mode == PlayMode.TEMPO ? Math.max(0, leadTicks) : 0;
		position = 0;
		cursor = 0;
		countIn = 0;
		hits = misses = wrong = 0;
		pressed.clear();
	}

	public void stop()
	{
		state = State.IDLE;
		position = 0;
		cursor = 0;
		countIn = 0;
		pressed.clear();
	}

	public boolean isActive()
	{
		return state == State.COUNT_IN || state == State.PLAYING;
	}

	/** True when the note at {@link #getCursor()} can be played now (its key is lit). */
	public boolean isTargetOpen()
	{
		if (!isActive() || song == null || cursor >= song.length())
		{
			return false;
		}
		if (mode == PlayMode.FOLLOW)
		{
			return state == State.PLAYING;
		}
		return cursor - dueBase() <= lead;
	}

	/** The note to play now, or null when nothing is open. */
	public Step current()
	{
		return isTargetOpen() ? song.getSteps().get(cursor) : null;
	}

	/** Index of the song's first note (leading rests skipped), or -1 if there is no song. */
	public int firstNoteIndex()
	{
		if (song == null)
		{
			return -1;
		}
		int i = firstNoteFrom(0);
		return i < song.length() ? i : -1;
	}

	/** The song's first note, which also starts the song when played. */
	public Step firstNote()
	{
		int i = firstNoteIndex();
		return i < 0 ? null : song.getSteps().get(i);
	}

	/**
	 * The step index that is "due now" for drawing the timeline: step {@code i} is due
	 * {@code i - dueBase()} ticks from now. Before a start it is the first note; during a
	 * count-in it lies in the future.
	 */
	public int dueBase()
	{
		switch (state)
		{
			case COUNT_IN:
				return -countIn;
			case PLAYING:
				return position;
			default:
				return Math.max(0, firstNoteIndex());
		}
	}

	/** Keys of the open note that still need pressing. */
	public Set<PianoKey> remaining()
	{
		Step step = current();
		if (step == null)
		{
			return Collections.emptySet();
		}
		Set<PianoKey> left = EnumSet.noneOf(PianoKey.class);
		left.addAll(step.getKeys());
		left.removeAll(pressed);
		return left;
	}

	/**
	 * The next {@code count} notes after the one to play now. In follow mode rests are
	 * left out; in tempo mode they are kept so the timing is visible.
	 */
	public List<Step> upcoming(int count)
	{
		List<Step> out = new ArrayList<>();
		if (song == null || !isActive())
		{
			return out;
		}
		int start = isTargetOpen() ? cursor + 1 : cursor;
		for (int i = start; i < song.length() && out.size() < count; i++)
		{
			Step step = song.getSteps().get(i);
			if (mode == PlayMode.FOLLOW && step.isRest())
			{
				continue;
			}
			out.add(step);
		}
		return out;
	}

	public PressResult press(PianoKey key)
	{
		Step step = current();
		if (step == null)
		{
			if (state == State.PLAYING && mode == PlayMode.TEMPO)
			{
				// Nothing lit: a stray or early key.
				wrong++;
				return PressResult.WRONG;
			}
			return PressResult.IGNORED;
		}
		if (!step.getKeys().contains(key))
		{
			// Don't get stuck on a note: count it and show the next one anyway.
			wrong++;
			misses++;
			nextNote();
			return PressResult.WRONG;
		}
		if (!pressed.add(key) || !remaining().isEmpty())
		{
			return PressResult.PARTIAL;
		}
		hits++;
		nextNote();
		return PressResult.HIT;
	}

	/** Called once per game tick. Only tempo mode moves with the clock. */
	public void tick()
	{
		if (mode != PlayMode.TEMPO)
		{
			return;
		}
		if (state == State.COUNT_IN)
		{
			if (--countIn <= 0)
			{
				state = State.PLAYING;
			}
			return;
		}
		if (state != State.PLAYING)
		{
			return;
		}
		position++;
		if (cursor < position)
		{
			// The note's own tick is over and it was not (fully) played.
			if (cursor < song.length() && !song.getSteps().get(cursor).isRest())
			{
				misses++;
			}
			pressed.clear();
			cursor = firstNoteFrom(position);
		}
		if (position >= song.length())
		{
			endOfSong();
		}
	}

	private void nextNote()
	{
		pressed.clear();
		cursor = firstNoteFrom(cursor + 1);
		if (mode == PlayMode.FOLLOW)
		{
			position = cursor;
			if (position >= song.length())
			{
				endOfSong();
			}
		}
	}

	private void endOfSong()
	{
		if (loop)
		{
			position = mode == PlayMode.FOLLOW ? firstNoteFrom(0) : 0;
			cursor = firstNoteFrom(position);
			pressed.clear();
		}
		else
		{
			state = State.FINISHED;
		}
	}

	private int firstNoteFrom(int index)
	{
		int i = index;
		while (song != null && i < song.length() && song.getSteps().get(i).isRest())
		{
			i++;
		}
		return i;
	}
}

package com.clanpiano;

import com.clanpiano.song.Song;
import com.clanpiano.song.Step;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A strip above the piano where the song's notes fall towards their keys, one row per game
 * tick. A note touches the line on top of the keys on the exact tick it should be played,
 * which is also when its key lights up green. The line flashes on every tick, like a
 * metronome, so the 0.6s beat can be felt before the first note.
 */
class TimingLaneOverlay extends Overlay
{
	private static final int PX_PER_TICK = 26;
	private static final Color LANE_BG = new Color(12, 12, 18, 175);
	private static final Color LANE_EDGE = new Color(255, 255, 255, 45);
	private static final Color GRID = new Color(255, 255, 255, 28);
	private static final Color NOTE_WHITE = new Color(90, 175, 255, 215);
	private static final Color NOTE_BLACK = new Color(165, 120, 255, 215);
	private static final Color PLAYED = new Color(140, 140, 140, 70);
	private static final Color TEXT = new Color(235, 235, 235);

	private final ClanPianoPlugin plugin;
	private final ClanPianoConfig config;
	private final PianoKeyOverlay keys;

	@Inject
	TimingLaneOverlay(ClanPianoPlugin plugin, ClanPianoConfig config, PianoKeyOverlay keys)
	{
		this.plugin = plugin;
		this.config = config;
		this.keys = keys;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.showTimingLane() || !plugin.isPianoOpen())
		{
			return null;
		}
		SongPlayer player = plugin.getPlayer();
		Song song = player.getSong();
		Rectangle lowC = keys.bounds(PianoKey.C4);
		Rectangle highB = keys.bounds(PianoKey.B5);
		Rectangle sharp = keys.bounds(PianoKey.CS4);
		if (song == null || lowC == null || highB == null || sharp == null)
		{
			return null;
		}

		int ticks = config.laneTicks();
		int hitY = sharp.y; // top edge of the keys
		int left = lowC.x - 4;
		int right = highB.x + highB.width + 4;
		Rectangle lane = new Rectangle(left, Math.max(0, hitY - ticks * PX_PER_TICK), right - left, 0);
		lane.height = hitY - lane.y;
		if (lane.height < PX_PER_TICK)
		{
			return null;
		}

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(LANE_BG);
		g.fill(lane);
		g.setColor(LANE_EDGE);
		g.setStroke(new BasicStroke(1));
		g.draw(lane);

		SongPlayer.State state = player.getState();
		double progress = plugin.tickProgress();

		Shape oldClip = g.getClip();
		g.clip(lane);

		// One faint line per tick, moving down with the notes.
		g.setColor(GRID);
		for (int k = 1; k <= ticks + 1; k++)
		{
			int y = (int) Math.round(hitY - (k - progress) * PX_PER_TICK);
			g.drawLine(lane.x, y, lane.x + lane.width, y);
		}

		if (state != SongPlayer.State.FINISHED)
		{
			drawNotes(g, player, song, hitY, ticks, progress);
		}
		g.setClip(oldClip);

		// The line the notes land on: flashes at the start of every tick.
		int alpha = state == SongPlayer.State.PLAYING || state == SongPlayer.State.COUNT_IN
			? (int) Math.round(80 + 175 * (1 - progress)) : 200;
		Color current = config.currentColor();
		g.setColor(new Color(current.getRed(), current.getGreen(), current.getBlue(), alpha));
		g.setStroke(new BasicStroke(3));
		g.drawLine(lane.x, hitY, lane.x + lane.width, hitY);

		drawCaption(g, player, lane);
		return null;
	}

	private void drawNotes(Graphics2D g, SongPlayer player, Song song, int hitY, int ticks, double progress)
	{
		int base = player.dueBase();
		g.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics fm = g.getFontMetrics();
		for (int i = Math.max(0, base); i < song.length() && i <= base + ticks + 1; i++)
		{
			Step step = song.getSteps().get(i);
			double due = i - base - progress; // ticks until this step should be played
			if (step.isRest() || due <= 0 || due > ticks + 1)
			{
				continue;
			}
			int bottom = (int) Math.round(hitY - due * PX_PER_TICK);
			// Green = its key is lit, play it now. Grey = already played, still landing.
			boolean open = i == player.getCursor() && player.isTargetOpen();
			boolean played = player.isActive() && i < player.getCursor();
			// White keys first so a black key's note is drawn on top.
			for (int pass = 0; pass < 2; pass++)
			{
				for (PianoKey key : step.getKeys())
				{
					if (key.isBlack() != (pass == 1))
					{
						continue;
					}
					Rectangle kb = keys.bounds(key);
					if (kb == null)
					{
						continue;
					}
					Rectangle block = new Rectangle(kb.x, bottom - (PX_PER_TICK - 4), kb.width, PX_PER_TICK - 4);
					Color fill = open ? config.currentColor() : played ? PLAYED : key.isBlack() ? NOTE_BLACK : NOTE_WHITE;
					g.setColor(fill);
					g.fillRoundRect(block.x, block.y, block.width, block.height, 6, 6);
					g.setColor(fill.darker());
					g.setStroke(new BasicStroke(1.5f));
					g.drawRoundRect(block.x, block.y, block.width, block.height, 6, 6);

					String name = key.displayName();
					int tw = fm.stringWidth(name);
					if (tw <= block.width)
					{
						int tx = block.x + (block.width - tw) / 2;
						int ty = block.y + (block.height + fm.getAscent()) / 2 - 1;
						g.setColor(Color.BLACK);
						g.drawString(name, tx + 1, ty + 1);
						g.setColor(TEXT);
						g.drawString(name, tx, ty);
					}
				}
			}
		}
	}

	private void drawCaption(Graphics2D g, SongPlayer player, Rectangle lane)
	{
		switch (player.getState())
		{
			case COUNT_IN:
				centered(g, lane, String.valueOf(player.getCountIn()), FontManager.getRunescapeBoldFont().deriveFont(28f), Color.YELLOW);
				break;
			case IDLE:
				top(g, lane, "Click the green key to start");
				break;
			case FINISHED:
				centered(g, lane, "Finished! " + player.getHits() + " / " + player.getSong().noteCount() + " notes",
					FontManager.getRunescapeBoldFont(), Color.GREEN);
				top(g, lane, "Click the green key to play again");
				break;
			default:
				break;
		}
	}

	private static void top(Graphics2D g, Rectangle lane, String text)
	{
		g.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics fm = g.getFontMetrics();
		int x = lane.x + (lane.width - fm.stringWidth(text)) / 2;
		int y = lane.y + fm.getAscent() + 3;
		shadowed(g, text, x, y, TEXT);
	}

	private static void centered(Graphics2D g, Rectangle lane, String text, Font font, Color color)
	{
		g.setFont(font);
		FontMetrics fm = g.getFontMetrics();
		int x = lane.x + (lane.width - fm.stringWidth(text)) / 2;
		int y = lane.y + (lane.height + fm.getAscent()) / 2;
		shadowed(g, text, x, y, color);
	}

	private static void shadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}
}

package com.clanpiano.song;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * A minimal reader for Standard MIDI Files (.mid): just enough to get the notes, program changes
 * and track names of each track. Plugins may not use the Java sound API, so the file is parsed here.
 */
final class MidiFile
{
	static final int NOTE_ON = 0x90;
	static final int PROGRAM_CHANGE = 0xC0;
	static final int META_TRACK_NAME = 0x03;

	/** One event in a track, at an absolute tick. Channel messages have a command; meta events a metaType. */
	static final class Event
	{
		final long tick;
		/** Upper nibble of the status byte (0x80..0xE0), or -1 for meta events. */
		final int command;
		final int channel;
		final int data1;
		final int data2;
		/** Meta event type, or -1 for channel messages. */
		final int metaType;
		final byte[] metaData;

		private Event(long tick, int command, int channel, int data1, int data2, int metaType, byte[] metaData)
		{
			this.tick = tick;
			this.command = command;
			this.channel = channel;
			this.data1 = data1;
			this.data2 = data2;
			this.metaType = metaType;
			this.metaData = metaData;
		}

		String metaText()
		{
			return new String(metaData, StandardCharsets.ISO_8859_1);
		}
	}

	/** Ticks per quarter note; for SMPTE-timed files, the ticks in half a second. */
	final double ticksPerBeat;
	final List<List<Event>> tracks;

	private MidiFile(double ticksPerBeat, List<List<Event>> tracks)
	{
		this.ticksPerBeat = ticksPerBeat;
		this.tracks = Collections.unmodifiableList(tracks);
	}

	static MidiFile parse(byte[] data)
	{
		Reader r = new Reader(data);
		if (!"MThd".equals(r.chunkType()))
		{
			throw new IllegalArgumentException("not a MIDI file (no MThd header)");
		}
		long headerLength = r.u32();
		if (headerLength < 6 || headerLength > r.remaining())
		{
			throw new IllegalArgumentException("MIDI header is damaged");
		}
		int headerEnd = r.pos + (int) headerLength;
		r.u16(); // format: 0, 1 and 2 are all read track by track
		int trackCount = r.u16();
		int division = r.u16();
		r.pos = headerEnd;

		double ticksPerBeat;
		if ((division & 0x8000) == 0)
		{
			ticksPerBeat = division;
		}
		else
		{
			// SMPTE timing: frames per second times ticks per frame is ticks per second.
			int framesPerSecond = -(byte) (division >> 8);
			int ticksPerFrame = division & 0xFF;
			ticksPerBeat = framesPerSecond * ticksPerFrame / 2.0;
		}
		if (ticksPerBeat <= 0)
		{
			throw new IllegalArgumentException("MIDI file has no timing information");
		}

		List<List<Event>> tracks = new ArrayList<>();
		while (tracks.size() < trackCount && r.remaining() >= 8)
		{
			String type = r.chunkType();
			long length = r.u32();
			int end = (int) Math.min(r.pos + length, data.length);
			if ("MTrk".equals(type))
			{
				tracks.add(readTrack(r, end));
			}
			r.pos = end;
		}
		if (tracks.isEmpty())
		{
			throw new IllegalArgumentException("MIDI file has no tracks");
		}
		return new MidiFile(ticksPerBeat, tracks);
	}

	private static List<Event> readTrack(Reader r, int end)
	{
		List<Event> events = new ArrayList<>();
		long tick = 0;
		int running = 0;
		// A damaged track keeps the events read so far.
		try
		{
			while (r.pos < end)
			{
				tick += r.varLength();
				int status = r.u8();
				if (status == 0xFF)
				{
					int type = r.u8();
					int length = (int) r.varLength();
					events.add(new Event(tick, -1, 0, 0, 0, type, r.bytes(length, end)));
					if (type == 0x2F)
					{
						break; // end of track
					}
					continue;
				}
				if (status == 0xF0 || status == 0xF7)
				{
					r.bytes((int) r.varLength(), end); // system exclusive: skip
					continue;
				}
				int data1;
				if (status < 0x80)
				{
					if (running == 0)
					{
						break; // data byte with no status to repeat
					}
					data1 = status;
					status = running;
				}
				else if (status >= 0xF0)
				{
					break; // system messages don't belong in a file
				}
				else
				{
					running = status;
					data1 = r.u8();
				}
				int command = status & 0xF0;
				int data2 = command == 0xC0 || command == 0xD0 ? 0 : r.u8();
				events.add(new Event(tick, command, status & 0x0F, data1 & 0x7F, data2 & 0x7F, -1, null));
			}
		}
		catch (IndexOutOfBoundsException e)
		{
			// Track ran past its chunk or the file: keep what was read.
		}
		return events;
	}

	private static final class Reader
	{
		private final byte[] data;
		private int pos;

		Reader(byte[] data)
		{
			this.data = data;
		}

		int remaining()
		{
			return data.length - pos;
		}

		int u8()
		{
			if (pos >= data.length)
			{
				throw new IndexOutOfBoundsException();
			}
			return data[pos++] & 0xFF;
		}

		int u16()
		{
			return (u8() << 8) | u8();
		}

		long u32()
		{
			return ((long) u16() << 16) | u16();
		}

		String chunkType()
		{
			if (remaining() < 4)
			{
				return "";
			}
			String type = new String(data, pos, 4, StandardCharsets.ISO_8859_1);
			pos += 4;
			return type;
		}

		long varLength()
		{
			long value = 0;
			for (int i = 0; i < 4; i++)
			{
				int b = u8();
				value = (value << 7) | (b & 0x7F);
				if ((b & 0x80) == 0)
				{
					return value;
				}
			}
			throw new IndexOutOfBoundsException(); // longer than the 4 bytes MIDI allows
		}

		byte[] bytes(int length, int end)
		{
			if (length < 0 || pos + length > end)
			{
				throw new IndexOutOfBoundsException();
			}
			byte[] out = new byte[length];
			System.arraycopy(data, pos, out, 0, length);
			pos += length;
			return out;
		}
	}
}

package com.clanpiano.song;

import com.clanpiano.PianoKey;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import lombok.extern.slf4j.Slf4j;

/**
 * Turns a MIDI file into a playable song for the 24-key, one-note-per-tick piano.
 *
 * <ol>
 * <li><b>Melody.</b> Every instrument part (track + channel, drums skipped) is scored, and the
 * busiest, highest, least chord-heavy part is taken as the tune. Where it still plays
 * several notes at once, the top note is kept.</li>
 * <li><b>Rhythm.</b> The song keeps its rhythm exactly: the largest note length that the
 * melody's notes line up with (a beat, an eighth, a sixteenth, a triplet...) becomes one game
 * tick, so the tune plays slower or faster but every note keeps its place.</li>
 * <li><b>Range.</b> The tune is moved by whole octaves (or, failing that, semitones) to fit
 * C4 to B5. Any note that still doesn't fit is moved by an octave into range.</li>
 * </ol>
 */
@Slf4j
public final class MidiImporter
{
	private static final int DRUM_CHANNEL = 9;
	private static final int LOW = PianoKey.LOWEST_MIDI;           // C4
	private static final int HIGH = PianoKey.LOWEST_MIDI + 23;     // B5
	/** Grid sizes tried, in beats, largest first. */
	private static final double[] GRIDS = {2, 1.5, 1, 2 / 3.0, 0.5, 1 / 3.0, 0.25, 1 / 6.0, 0.125};
	/**
	 * Share of melody notes that must sit on the grid, and how many may be lost where two land
	 * on one tick. A few grace notes and fast runs are given up so the song keeps a playable
	 * tempo instead of crawling along one sixteenth per tick.
	 */
	private static final double ON_GRID = 0.85;
	private static final double MAX_DROPPED = 0.12;
	/** Songs are cut to about this many ticks (2.4 minutes); game tracks loop for much longer. */
	static final int MAX_STEPS = 240;
	/** Song files bigger than this are not MIDI songs anyone wants to play. */
	private static final int MAX_FILE_BYTES = 4 * 1024 * 1024;
	/** How much of the start of the song is used to judge which part is the tune. */
	private static final double OPENING_BEATS = 96;
	/** Candidate melodies kept per file, so a wrong first guess can be switched by ear. */
	private static final int MAX_VERSIONS = 4;

	private MidiImporter()
	{
	}

	/** One note-on in the file, in MIDI ticks. */
	static final class Note
	{
		final long tick;
		final int pitch;

		Note(long tick, int pitch)
		{
			this.tick = tick;
			this.pitch = pitch;
		}
	}

	public static Song load(InputStream in, String title, String source) throws IOException
	{
		return convert(MidiFile.parse(readAll(in)), title, source);
	}

	private static byte[] readAll(InputStream in) throws IOException
	{
		java.io.ByteArrayOutputStream out = new java.io.ByteArrayOutputStream();
		byte[] buf = new byte[8192];
		int n;
		while ((n = in.read(buf)) > 0)
		{
			out.write(buf, 0, n);
			if (out.size() > MAX_FILE_BYTES)
			{
				throw new IllegalArgumentException("MIDI file is too big");
			}
		}
		return out.toByteArray();
	}

	static Song convert(MidiFile midi, String title, String source)
	{
		double ticksPerBeat = midi.ticksPerBeat;

		// Collect notes per part (track + channel).
		Map<String, List<Note>> parts = new HashMap<>();
		Map<String, String> partNames = new HashMap<>();
		Map<String, Integer> programs = new HashMap<>();
		for (int t = 0; t < midi.tracks.size(); t++)
		{
			String trackName = null;
			for (MidiFile.Event event : midi.tracks.get(t))
			{
				if (event.metaType == MidiFile.META_TRACK_NAME)
				{
					trackName = event.metaText().trim();
				}
				if (event.command < 0)
				{
					continue;
				}
				if (event.command == MidiFile.PROGRAM_CHANGE)
				{
					programs.putIfAbsent(t + ":" + event.channel, event.data1);
				}
				if (event.command != MidiFile.NOTE_ON || event.data2 == 0 || event.channel == DRUM_CHANNEL)
				{
					continue;
				}
				String key = t + ":" + event.channel;
				parts.computeIfAbsent(key, k -> new ArrayList<>()).add(new Note(event.tick, event.data1));
				if (trackName != null && !trackName.isEmpty())
				{
					partNames.putIfAbsent(key, trackName);
				}
			}
		}
		if (parts.isEmpty())
		{
			throw new IllegalArgumentException("MIDI file has no notes (only drums or empty)");
		}

		// Rank the parts by how much they look like the tune during the song's opening, which is
		// the part that gets played. Keep the best few so the player can switch by ear.
		long songStart = Long.MAX_VALUE;
		long songEnd = 0;
		for (List<Note> notes : parts.values())
		{
			for (Note n : notes)
			{
				songStart = Math.min(songStart, n.tick);
				songEnd = Math.max(songEnd, n.tick);
			}
		}
		long windowEnd = Math.min(songEnd, songStart + (long) (OPENING_BEATS * ticksPerBeat));
		List<Map.Entry<String, Double>> ranked = new ArrayList<>();
		for (Map.Entry<String, List<Note>> e : parts.entrySet())
		{
			List<Note> opening = new ArrayList<>();
			for (Note n : e.getValue())
			{
				if (n.tick <= windowEnd)
				{
					opening.add(n);
				}
			}
			double score = melodyScore(opening)
				* coverage(opening, songStart, windowEnd, ticksPerBeat)
				* programWeight(programs.getOrDefault(e.getKey(), 0));
			if (score > 0)
			{
				ranked.add(new java.util.AbstractMap.SimpleEntry<>(e.getKey(), score));
			}
		}
		if (ranked.isEmpty())
		{
			throw new IllegalArgumentException("MIDI file has no part that looks like a melody");
		}
		ranked.sort((a, b) -> Double.compare(b.getValue(), a.getValue()));

		List<Song> versions = new ArrayList<>();
		Map<String, Integer> labelCount = new HashMap<>();
		for (Map.Entry<String, Double> e : ranked)
		{
			if (versions.size() >= MAX_VERSIONS)
			{
				break;
			}
			String part = e.getKey();
			List<Step> steps = arrange(parts.get(part), ticksPerBeat, source + " " + part);
			// Alternatives must be worth playing; the best guess is kept whatever its length.
			if (!versions.isEmpty() && steps.stream().filter(st -> !st.isRest()).count() < 8)
			{
				continue;
			}
			String instrument = programs.containsKey(part) ? instrumentName(programs.get(part)) : "piano";
			int n = labelCount.merge(instrument, 1, Integer::sum);
			String label = n == 1 ? instrument : instrument + " " + n;
			versions.add(new Song(title, "From MIDI, " + label, source, steps).withPart(label));
		}
		if (versions.isEmpty())
		{
			throw new IllegalArgumentException("MIDI file's parts are too short to play");
		}
		log.debug("MIDI {}: {} parts, melody candidates {}", source, parts.size(), ranked);
		return versions.get(0).withAlternatives(versions.subList(1, versions.size()));
	}

	/** One part as piano steps: top line, rhythm grid, cut to length, fitted to the keys. */
	private static List<Step> arrange(List<Note> notes, double ticksPerBeat, String what)
	{
		List<Note> melody = topLine(notes);
		double grid = pickGrid(melody, ticksPerBeat);
		double slotTicks = grid * ticksPerBeat;
		long first = melody.get(0).tick;
		TreeMap<Integer, Integer> slots = new TreeMap<>();
		Map<Integer, Double> slotError = new HashMap<>();
		int dropped = 0;
		for (Note n : melody)
		{
			double pos = (n.tick - first) / slotTicks;
			int slot = (int) Math.round(pos);
			if (slot >= MAX_STEPS)
			{
				break;
			}
			double error = Math.abs(pos - slot);
			Double had = slotError.get(slot);
			if (had != null)
			{
				// Two notes on one tick: keep the one that sits on the beat, not the grace note.
				dropped++;
				if (had <= error)
				{
					continue;
				}
			}
			slots.put(slot, n.pitch);
			slotError.put(slot, error);
		}

		int shift = pickShift(new ArrayList<>(slots.values()));
		int folded = 0;
		List<Step> steps = new ArrayList<>();
		for (int i = 0; i <= slots.lastKey(); i++)
		{
			Integer pitch = slots.get(i);
			if (pitch == null)
			{
				steps.add(Step.REST);
				continue;
			}
			int p = pitch + shift;
			if (p < LOW || p > HIGH)
			{
				folded++;
				while (p < LOW)
				{
					p += 12;
				}
				while (p > HIGH)
				{
					p -= 12;
				}
			}
			steps.add(new Step(EnumSet.of(PianoKey.fromMidi(p))));
		}
		log.debug("  {}: 1 tick = {} beats, shift {}, {} doubled notes dropped, {} folded", what, grid, shift, dropped, folded);
		return steps;
	}

	/** Share of two-beat windows in the opening where the part plays something. */
	static double coverage(List<Note> notes, long start, long end, double ticksPerBeat)
	{
		double window = 2 * ticksPerBeat;
		int windows = Math.max(1, (int) Math.ceil((end - start + 1) / window));
		java.util.Set<Integer> hit = new java.util.HashSet<>();
		for (Note n : notes)
		{
			hit.add((int) ((n.tick - start) / window));
		}
		return Math.min(1, hit.size() / (double) windows);
	}

	/** Busy, high and mostly one-note-at-a-time parts look like a melody. */
	static double melodyScore(List<Note> notes)
	{
		if (notes.size() < 4)
		{
			return 0;
		}
		Map<Long, Integer> perTick = new HashMap<>();
		double pitchSum = 0;
		for (Note n : notes)
		{
			perTick.merge(n.tick, 1, Integer::sum);
			pitchSum += n.pitch;
		}
		double chordiness = 1 - perTick.size() / (double) notes.size();
		double meanPitch = pitchSum / notes.size();
		// Tunes sit in the middle-high register; very high parts are usually sparkle or trills.
		double register = Math.max(0.2, 1 - Math.abs(meanPitch - 74) / 30.0);
		// Tunes mostly move by step; arpeggios and accompaniment jump around in thirds and fourths.
		// Repeating one note over and over is rhythm, not a tune, so repeats count for little.
		List<Note> line = topLine(notes);
		double steps = 0;
		java.util.Set<Integer> pitches = new java.util.HashSet<>();
		for (int i = 0; i < line.size(); i++)
		{
			pitches.add(line.get(i).pitch);
			if (i == 0)
			{
				continue;
			}
			int jump = Math.abs(line.get(i).pitch - line.get(i - 1).pitch);
			steps += jump == 0 ? 0.25 : jump <= 2 ? 1 : 0;
		}
		double stepwise = line.size() < 2 ? 0 : steps / (line.size() - 1);
		double variety = Math.min(1, pitches.size() / 6.0);
		return Math.sqrt(perTick.size()) * (1 - 0.8 * chordiness) * register * variety * (0.15 + stepwise);
	}

	/** General MIDI programs: lead instruments carry tunes, harps and pads accompany, percussion never. */
	static double programWeight(int program)
	{
		if (program >= 112 || program == 47 || program == 55)
		{
			return 0; // percussive, sound effects, timpani, orchestra hit
		}
		if ((program >= 40 && program <= 41) || (program >= 52 && program <= 54) || (program >= 56 && program <= 61)
			|| (program >= 64 && program <= 79) || program == 22 || program == 23 || program == 105 || program == 109
			|| program == 110 || program == 111 || (program >= 80 && program <= 81))
		{
			return 1.4; // violin, voices, brass, reeds, pipes, harmonica, bagpipe, fiddle, leads
		}
		if (program == 46 || (program >= 8 && program <= 15) || (program >= 24 && program <= 31) || program == 45
			|| program == 104 || program == 106 || program == 107)
		{
			return 0.6; // harp, mallets and bells, guitars, pizzicato, plucked
		}
		if ((program >= 32 && program <= 39) || (program >= 88 && program <= 95) || (program >= 48 && program <= 51)
			|| program == 42 || program == 43)
		{
			return 0.35; // basses, pads, string ensembles, cello, contrabass
		}
		return 1.0;
	}

	private static final String[] FAMILIES = {
		"piano", "chromatic percussion", "organ", "guitar", "bass", "strings", "ensemble", "brass",
		"reed", "pipe", "synth lead", "synth pad", "synth effects", "ethnic", "percussive", "sound effects",
	};

	private static String instrumentName(int program)
	{
		switch (program)
		{
			case 40: return "violin";
			case 46: return "harp";
			case 56: return "trumpet";
			case 60: return "french horn";
			case 68: return "oboe";
			case 69: return "english horn";
			case 71: return "clarinet";
			case 72: return "piccolo";
			case 73: return "flute";
			case 74: return "recorder";
			case 75: return "pan flute";
			case 79: return "ocarina";
			case 105: return "banjo";
			case 109: return "bagpipe";
			case 110: return "fiddle";
			default: return FAMILIES[Math.max(0, Math.min(127, program)) / 8];
		}
	}

	/** Keeps the highest note wherever several start together. */
	static List<Note> topLine(List<Note> notes)
	{
		TreeMap<Long, Integer> top = new TreeMap<>();
		for (Note n : notes)
		{
			top.merge(n.tick, n.pitch, Math::max);
		}
		List<Note> out = new ArrayList<>();
		top.forEach((tick, pitch) -> out.add(new Note(tick, pitch)));
		return out;
	}

	/** The largest grid (in beats) the melody fits, so the song plays as briskly as the rhythm allows. */
	static double pickGrid(List<Note> melody, double ticksPerBeat)
	{
		long first = melody.get(0).tick;
		for (double grid : GRIDS)
		{
			double slotTicks = grid * ticksPerBeat;
			int onGrid = 0;
			Map<Long, Integer> used = new HashMap<>();
			for (Note n : melody)
			{
				double pos = (n.tick - first) / slotTicks;
				long slot = Math.round(pos);
				if (Math.abs(pos - slot) <= 0.12)
				{
					onGrid++;
				}
				used.merge(slot, 1, Integer::sum);
			}
			int doubled = melody.size() - used.size();
			if (onGrid >= ON_GRID * melody.size() && doubled <= MAX_DROPPED * melody.size())
			{
				return grid;
			}
		}
		return GRIDS[GRIDS.length - 1];
	}

	/** Semitone shift that fits the most notes on the keyboard, preferring whole octaves and small moves. */
	static int pickShift(List<Integer> pitches)
	{
		int best = 0;
		long bestKey = Long.MIN_VALUE;
		for (int shift = -60; shift <= 60; shift++)
		{
			int fit = 0;
			for (int p : pitches)
			{
				if (p + shift >= LOW && p + shift <= HIGH)
				{
					fit++;
				}
			}
			// Rank: most notes fitting, then octave moves (keeps the key), then the smallest move.
			long key = (long) fit * 1_000_000 + (shift % 12 == 0 ? 10_000 : 0) - Math.abs(shift);
			if (key > bestKey)
			{
				bestKey = key;
				best = shift;
			}
		}
		return best;
	}
}

package com.clanpiano.song;

import com.clanpiano.PianoKey;
import java.util.Collections;
import java.util.List;
import lombok.Getter;

/**
 * A song quantised to game ticks: step i is played on tick i.
 * One tick is 0.6 seconds, so 100 steps last one minute.
 */
@Getter
public final class Song
{
	public enum Difficulty
	{
		EASY("Easy"),
		MEDIUM("Medium"),
		HARD("Hard");

		private final String label;

		Difficulty(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	private final String title;
	private final String artist;
	private final String source; // "built-in" or the file it came from
	private final List<Step> steps;
	/** The song selector folder this song is listed under. */
	private final String folder;
	/** For MIDI songs: which instrument part the melody was taken from, else empty. */
	private final String part;
	/** For MIDI songs: other parts that might be the tune, to switch to by ear. */
	private final List<Song> alternatives;

	public Song(String title, String artist, String source, List<Step> steps)
	{
		this(title, artist, source, steps, "", "", Collections.emptyList());
	}

	private Song(String title, String artist, String source, List<Step> steps, String folder, String part, List<Song> alternatives)
	{
		this.title = title;
		this.artist = artist;
		this.source = source;
		this.steps = Collections.unmodifiableList(steps);
		this.folder = folder;
		this.part = part;
		this.alternatives = Collections.unmodifiableList(alternatives);
	}

	public Song inFolder(String folder)
	{
		List<Song> alts = new java.util.ArrayList<>();
		alternatives.forEach(a -> alts.add(a.inFolder(folder)));
		return new Song(title, artist, source, steps, folder, part, alts);
	}

	public Song withPart(String part)
	{
		return new Song(title, artist, source, steps, folder, part, alternatives);
	}

	public Song withAlternatives(List<Song> alternatives)
	{
		return new Song(title, artist, source, steps, folder, part, alternatives);
	}

	/** This song and its alternatives: every melody version to choose from. */
	public List<Song> versions()
	{
		List<Song> all = new java.util.ArrayList<>();
		all.add(this);
		all.addAll(alternatives);
		return all;
	}

	/** Stable name for remembering favourites and the last song: folder and title. */
	public String id()
	{
		return folder + "/" + title;
	}

	public PianoKey lowestKey()
	{
		PianoKey low = null;
		for (Step step : steps)
		{
			for (PianoKey key : step.getKeys())
			{
				if (low == null || key.ordinal() < low.ordinal())
				{
					low = key;
				}
			}
		}
		return low;
	}

	public PianoKey highestKey()
	{
		PianoKey high = null;
		for (Step step : steps)
		{
			for (PianoKey key : step.getKeys())
			{
				if (high == null || key.ordinal() > high.ordinal())
				{
					high = key;
				}
			}
		}
		return high;
	}

	/**
	 * A rough guide from how busy the song is: notes on most ticks, sharps, big jumps
	 * across the keyboard and sheer length each make it harder.
	 */
	public Difficulty difficulty()
	{
		int notes = 0;
		int sharps = 0;
		int jumpTotal = 0;
		int jumps = 0;
		int previous = -1;
		for (Step step : steps)
		{
			if (step.isRest())
			{
				continue;
			}
			notes++;
			PianoKey first = step.getKeys().iterator().next();
			if (step.getKeys().stream().anyMatch(PianoKey::isBlack))
			{
				sharps++;
			}
			if (previous >= 0)
			{
				jumpTotal += Math.abs(first.ordinal() - previous);
				jumps++;
			}
			previous = first.ordinal();
		}
		if (notes == 0)
		{
			return Difficulty.EASY;
		}
		int score = 0;
		if (notes / (double) steps.size() > 0.75)
		{
			score++;
		}
		if (sharps / (double) notes > 0.12)
		{
			score++;
		}
		if (jumps > 0 && jumpTotal / (double) jumps > 2.6)
		{
			score++;
		}
		if (notes > 70)
		{
			score++;
		}
		return score <= 1 ? Difficulty.EASY : score == 2 ? Difficulty.MEDIUM : Difficulty.HARD;
	}

	/** Length as m:ss at one step per tick. */
	public String duration()
	{
		int total = (int) Math.round(seconds());
		return total / 60 + ":" + String.format("%02d", total % 60);
	}

	public int length()
	{
		return steps.size();
	}

	public int noteCount()
	{
		int count = 0;
		for (Step step : steps)
		{
			if (!step.isRest())
			{
				count++;
			}
		}
		return count;
	}

	/** Length in seconds when played at one step per tick. */
	public double seconds()
	{
		return steps.size() * 0.6;
	}

	@Override
	public String toString()
	{
		return artist == null || artist.isEmpty() ? title : title + " - " + artist;
	}
}

package com.clanpiano.song;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Built-in songs live in resources under /songs, listed in /songs/index.txt, where a line
 * like {@code [Classical]} starts a folder. Players can add their own .txt songs to a folder
 * in the RuneLite directory: loose files go under "My songs", and each subfolder becomes a
 * folder of its own in the song selector. Files are read through RuneLite's {@link Filepath},
 * which keeps the plugin inside its own data folder. Song files are .txt in the note format, or MIDI
 * (.mid/.midi), which {@link MidiImporter} turns into a playable melody.
 */
@Slf4j
public final class SongLibrary
{
	private static final String INDEX = "/songs/index.txt";
	public static final String DEFAULT_FOLDER = "Songs";
	public static final String MY_SONGS = "My songs";

	@Getter
	private final Filepath customDir;
	@Getter
	private List<Song> songs = Collections.emptyList();
	/** Folder names in display order, including custom folders that are still empty. */
	@Getter
	private List<String> folders = Collections.emptyList();
	/** Custom folders that exist on disk, so the selector can offer to open them. */
	@Getter
	private Set<String> customFolders = Collections.emptySet();
	@Getter
	private List<String> errors = Collections.emptyList();

	public SongLibrary(Filepath customDir)
	{
		this.customDir = customDir;
	}

	public void reload()
	{
		List<Song> loaded = new ArrayList<>();
		Set<String> folderOrder = new LinkedHashSet<>();
		Set<String> custom = new LinkedHashSet<>();
		List<String> problems = new ArrayList<>();

		String folder = DEFAULT_FOLDER;
		for (String line : readResource(INDEX).split("\\r?\\n"))
		{
			line = line.trim();
			if (line.isEmpty() || line.startsWith("//"))
			{
				continue;
			}
			if (line.startsWith("[") && line.endsWith("]"))
			{
				folder = line.substring(1, line.length() - 1).trim();
				continue;
			}
			try
			{
				loaded.add(SongParser.parse(readResource("/songs/" + line), stripExtension(line), "built-in").inFolder(folder));
				folderOrder.add(folder);
			}
			catch (RuntimeException e)
			{
				log.warn("Built-in song {} failed to load", line, e);
				problems.add(line + ": " + e.getMessage());
			}
		}

		if (customDir != null)
		{
			try
			{
				customDir.createDirectories();
				List<Song> mine = loadDir(customDir, MY_SONGS, problems);
				if (!mine.isEmpty())
				{
					loaded.addAll(mine);
					folderOrder.add(MY_SONGS);
					custom.add(MY_SONGS);
				}
				List<Filepath> subdirs = children(customDir);
				subdirs.removeIf(p -> !p.isDirectory());
				subdirs.sort(Comparator.comparing(Filepath::getFileName, String.CASE_INSENSITIVE_ORDER));
				for (Filepath dir : subdirs)
				{
					String name = dir.getFileName();
					loaded.addAll(loadDir(dir, name, problems));
					folderOrder.add(name);
					custom.add(name);
				}
			}
			catch (IOException e)
			{
				log.warn("Could not read custom song folder {}", customDir, e);
				problems.add("custom folder: " + e.getMessage());
			}
		}

		songs = Collections.unmodifiableList(loaded);
		folders = Collections.unmodifiableList(new ArrayList<>(folderOrder));
		customFolders = Collections.unmodifiableSet(custom);
		errors = Collections.unmodifiableList(problems);
	}

	/** Where a folder lives on disk, for custom folders. */
	public Filepath pathOf(String folder)
	{
		if (customDir == null || folder == null || !customFolders.contains(folder) || MY_SONGS.equals(folder))
		{
			return customDir;
		}
		return customDir.joinSegment(folder);
	}

	/** The files and folders directly inside {@code dir}. */
	private static List<Filepath> children(Filepath dir) throws IOException
	{
		try (Stream<Filepath> walk = dir.walk(1))
		{
			return walk.filter(p -> !p.equals(dir)).collect(Collectors.toCollection(ArrayList::new));
		}
	}

	private static List<Song> loadDir(Filepath dir, String folder, List<String> problems) throws IOException
	{
		List<Song> out = new ArrayList<>();
		for (Filepath path : children(dir))
		{
			String name = path.getFileName();
			String lower = name.toLowerCase(Locale.ROOT);
			boolean text = lower.endsWith(".txt");
			if (!path.isFile() || !(text || lower.endsWith(".mid") || lower.endsWith(".midi")))
			{
				continue;
			}
			try
			{
				Song song;
				if (text)
				{
					try (BufferedReader reader = path.openBufferedReader())
					{
						song = SongParser.parse(reader.lines().collect(Collectors.joining("\n")), stripExtension(name), name);
					}
				}
				else
				{
					try (InputStream in = new java.io.BufferedInputStream(path.openInputStream()))
					{
						song = MidiImporter.load(in, stripExtension(name), name);
					}
				}
				out.add(song.inFolder(folder));
			}
			catch (IOException | RuntimeException e)
			{
				problems.add((MY_SONGS.equals(folder) ? "" : folder + "/") + name + ": " + e.getMessage());
			}
		}
		out.sort(Comparator.comparing(Song::getTitle, String.CASE_INSENSITIVE_ORDER));
		return out;
	}

	private static String readResource(String path)
	{
		InputStream in = SongLibrary.class.getResourceAsStream(path);
		if (in == null)
		{
			throw new IllegalStateException("missing resource " + path);
		}
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			return reader.lines().collect(Collectors.joining("\n"));
		}
		catch (IOException e)
		{
			throw new IllegalStateException("could not read " + path, e);
		}
	}

	private static String stripExtension(String file)
	{
		int dot = file.lastIndexOf('.');
		return dot > 0 ? file.substring(0, dot) : file;
	}
}

package com.clanpiano.song;

import com.clanpiano.PianoKey;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Parses the plain-text song format. Every token is one game tick (0.6s):
 *
 * <pre>
 * title: Ode to Joy
 * artist: Beethoven
 * transpose: 0          // optional, in semitones
 *
 * E5 E5 F5 G5 | G5 F5 E5 D5     // one note per tick; '|' is ignored
 * C5*2                          // C5, then hold for one more tick
 * -  -*3                        // rest one tick, rest three ticks
 * C4+E4+G4                      // chord: keys pressed on the same tick
 * </pre>
 *
 * Notes are a letter A-G, an optional '#' or 'b', and an octave number.
 * After transposing, every note must land between C4 and B5.
 * Text after '//' on a line is a comment.
 */
public final class SongParser
{
	private static final Pattern HEADER = Pattern.compile("^\\s*([A-Za-z]+)\\s*:\\s*(.*)$");
	private static final Pattern NOTE = Pattern.compile("^([A-Ga-g])([#b]?)(-?\\d)$");
	private static final Pattern DURATION = Pattern.compile("^(.*?)\\*(\\d+)$");
	private static final int MAX_DURATION = 64;

	private SongParser()
	{
	}

	public static Song parse(String text, String fallbackTitle, String source)
	{
		String title = fallbackTitle;
		String artist = "";
		int transpose = 0;
		List<String[]> bodyTokens = new ArrayList<>(); // {token, line number}

		String[] lines = text.split("\\r?\\n", -1);
		for (int i = 0; i < lines.length; i++)
		{
			int lineNo = i + 1;
			String line = stripComment(lines[i]);
			if (line.trim().isEmpty())
			{
				continue;
			}

			Matcher header = HEADER.matcher(line);
			if (header.matches())
			{
				String name = header.group(1).toLowerCase(Locale.ROOT);
				String value = header.group(2).trim();
				switch (name)
				{
					case "title":
						title = value;
						break;
					case "artist":
					case "composer":
					case "by":
						artist = value;
						break;
					case "transpose":
						try
						{
							transpose = Integer.parseInt(value);
						}
						catch (NumberFormatException e)
						{
							throw error(lineNo, "transpose must be a whole number of semitones, got '" + value + "'");
						}
						break;
					default:
						// Unknown headers are kept for forward compatibility and ignored.
						break;
				}
				continue;
			}

			for (String token : line.trim().split("\\s+"))
			{
				if (!token.isEmpty() && !token.equals("|"))
				{
					bodyTokens.add(new String[]{token, String.valueOf(lineNo)});
				}
			}
		}

		List<Step> steps = new ArrayList<>();
		for (String[] entry : bodyTokens)
		{
			parseToken(entry[0], Integer.parseInt(entry[1]), transpose, steps);
		}

		// Trailing rests add nothing but dead time.
		while (!steps.isEmpty() && steps.get(steps.size() - 1).isRest())
		{
			steps.remove(steps.size() - 1);
		}
		if (steps.isEmpty())
		{
			throw new IllegalArgumentException("song '" + title + "' has no notes");
		}
		return new Song(title, artist, source, steps);
	}

	private static void parseToken(String token, int lineNo, int transpose, List<Step> steps)
	{
		String body = token;
		int duration = 1;
		Matcher dm = DURATION.matcher(token);
		if (dm.matches())
		{
			body = dm.group(1);
			duration = Integer.parseInt(dm.group(2));
			if (duration < 1 || duration > MAX_DURATION)
			{
				throw error(lineNo, "duration in '" + token + "' must be 1 to " + MAX_DURATION);
			}
		}

		Step step;
		if (body.equals("-") || body.equals("."))
		{
			step = Step.REST;
		}
		else
		{
			Set<PianoKey> keys = EnumSet.noneOf(PianoKey.class);
			for (String part : body.split("\\+"))
			{
				keys.add(parseNote(part, lineNo, transpose));
			}
			step = new Step(keys);
		}

		steps.add(step);
		for (int i = 1; i < duration; i++)
		{
			steps.add(Step.REST);
		}
	}

	static PianoKey parseNote(String text, int lineNo, int transpose)
	{
		Matcher m = NOTE.matcher(text);
		if (!m.matches())
		{
			throw error(lineNo, "'" + text + "' is not a note (expected something like C4, F#5 or Bb4)");
		}
		int pitchClass = "C D EF G A B".indexOf(Character.toUpperCase(m.group(1).charAt(0)));
		int accidental = m.group(2).equals("#") ? 1 : m.group(2).equals("b") ? -1 : 0;
		int octave = Integer.parseInt(m.group(3));
		int midi = (octave + 1) * 12 + pitchClass + accidental + transpose;
		PianoKey key = PianoKey.fromMidi(midi);
		if (key == null)
		{
			throw error(lineNo, "'" + text + "'" + (transpose != 0 ? " transposed by " + transpose : "")
				+ " is outside the piano's range (C4 to B5)");
		}
		return key;
	}

	private static String stripComment(String line)
	{
		int idx = line.indexOf("//");
		return idx >= 0 ? line.substring(0, idx) : line;
	}

	private static IllegalArgumentException error(int lineNo, String message)
	{
		return new IllegalArgumentException("line " + lineNo + ": " + message);
	}
}

package com.clanpiano.song;

import com.clanpiano.PianoKey;
import java.util.Collections;
import java.util.EnumSet;
import java.util.Set;
import java.util.stream.Collectors;

/** What to play on one tick: nothing (a rest), one key, or a chord. */
public final class Step
{
	public static final Step REST = new Step(EnumSet.noneOf(PianoKey.class));

	private final Set<PianoKey> keys;

	public Step(Set<PianoKey> keys)
	{
		this.keys = Collections.unmodifiableSet(keys.isEmpty() ? EnumSet.noneOf(PianoKey.class) : EnumSet.copyOf(keys));
	}

	public Set<PianoKey> getKeys()
	{
		return keys;
	}

	public boolean isRest()
	{
		return keys.isEmpty();
	}

	public String label()
	{
		if (keys.isEmpty())
		{
			return "-";
		}
		return keys.stream().map(PianoKey::displayName).collect(Collectors.joining("+"));
	}

	@Override
	public String toString()
	{
		return label();
	}
}

