package com.clanpiano;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.clanpiano.song.MidiImporter;
import com.clanpiano.song.Song;
import com.clanpiano.song.SongLibrary;
import com.clanpiano.song.Step;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.stream.Collectors;
import javax.sound.midi.MetaMessage;
import javax.sound.midi.MidiEvent;
import javax.sound.midi.MidiSystem;
import javax.sound.midi.Sequence;
import javax.sound.midi.ShortMessage;
import javax.sound.midi.Track;
import org.junit.Test;

public class MidiImporterTest
{
	private static final int PPQ = 480;

	@Test
	public void picksTheMelodyOverBassAndDrumsAndKeepsItsRhythm() throws Exception
	{
		Sequence seq = new Sequence(Sequence.PPQ, PPQ);
		Track melody = named(seq, "Flute");
		// C5 D5 E5 (quarters), rest a beat, G5 (quarter): one beat = one tick
		note(melody, 0, 0, 72);
		note(melody, 0, 1, 74);
		note(melody, 0, 2, 76);
		note(melody, 0, 4, 79);
		note(melody, 0, 5, 76);
		Track bass = named(seq, "Bass");
		for (int beat = 0; beat < 6; beat += 2)
		{
			note(bass, 1, beat, 36); // long low notes
		}
		Track drums = named(seq, "Drums");
		for (int beat = 0; beat < 6; beat++)
		{
			note(drums, 9, beat, 38);
			note(drums, 9, beat + 0.5, 42);
		}

		Song song = MidiImporter.load(bytes(seq), "Test", "test.mid");
		assertEquals("C' D' E' - G' E'", labels(song));
		assertEquals("piano", song.getPart());
		assertEquals(1, song.versions().size()); // bass too short, drums never
	}

	@Test
	public void otherMelodicPartsAreKeptAsVersionsToSwitchTo() throws Exception
	{
		Sequence seq = sequence();
		Track flute = named(seq, "Flute");
		flute.add(new MidiEvent(new ShortMessage(ShortMessage.PROGRAM_CHANGE, 0, 73, 0), 0));
		Track violin = named(seq, "Violin");
		violin.add(new MidiEvent(new ShortMessage(ShortMessage.PROGRAM_CHANGE, 1, 40, 0), 0));
		int[] tune = {72, 74, 76, 77, 79, 77, 76, 74, 72, 71, 72, 74};
		int[] counter = {60, 62, 64, 65, 67, 65, 64, 62, 60, 59, 60, 62};
		for (int i = 0; i < tune.length; i++)
		{
			note(flute, 0, i, tune[i]);
			note(violin, 1, i, counter[i]);
		}
		Song song = MidiImporter.load(bytes(seq), "Duet", "duet.mid");
		assertEquals(2, song.versions().size());
		assertEquals("flute", song.getPart()); // higher register wins
		assertEquals("violin", song.getAlternatives().get(0).getPart());
		assertEquals("RuneScape", song.inFolder("RuneScape").getAlternatives().get(0).getFolder());
	}

	@Test
	public void eighthNotesBecomeOneTickEach()
	{
		Sequence seq = sequence();
		Track t = named(seq, "Lead");
		double[] beats = {0, 0.5, 1, 2, 2.5, 3};
		int[] pitches = {67, 69, 71, 72, 71, 69};
		for (int i = 0; i < beats.length; i++)
		{
			note(t, 0, beats[i], pitches[i]);
		}
		Song song = convert(seq);
		assertEquals("G A B - C' B A", labels(song));
	}

	@Test
	public void lowTunesMoveUpByOctavesToFitTheKeys()
	{
		Sequence seq = sequence();
		Track t = named(seq, "Cello");
		int[] pitches = {48, 52, 55, 60}; // C3 E3 G3 C4
		for (int i = 0; i < pitches.length; i++)
		{
			note(t, 0, i, pitches[i]);
		}
		assertEquals("C E G C'", labels(convert(seq)));
	}

	@Test
	public void midiFilesInSongFoldersLoad() throws Exception
	{
		Sequence seq = sequence();
		Track t = named(seq, "Lead");
		for (int i = 0; i < 8; i++)
		{
			note(t, 0, i, 60 + i);
		}
		Path dir = Files.createTempDirectory("piano-midi");
		Files.createDirectories(dir.resolve("RuneScape"));
		MidiSystem.write(seq, 1, dir.resolve("RuneScape").resolve("Scale Tune.mid").toFile());

		SongLibrary library = new SongLibrary(net.runelite.client.util.Filepath.Unchecked.getRooted(dir));
		library.reload();
		assertEquals("errors: " + library.getErrors(), 0, library.getErrors().size());
		Song song = library.getSongs().stream().filter(s -> s.getTitle().equals("Scale Tune")).findFirst().get();
		assertEquals("RuneScape", song.getFolder());
		assertEquals(8, song.noteCount());
	}

	// ---- helpers ----

	private static Sequence sequence()
	{
		try
		{
			return new Sequence(Sequence.PPQ, PPQ);
		}
		catch (Exception e)
		{
			throw new IllegalStateException(e);
		}
	}

	private static Song convert(Sequence seq)
	{
		try
		{
			return MidiImporter.load(bytes(seq), "t", "t.mid");
		}
		catch (Exception e)
		{
			throw new IllegalStateException(e);
		}
	}

	private static Track named(Sequence seq, String name)
	{
		try
		{
			Track t = seq.createTrack();
			byte[] data = name.getBytes();
			t.add(new MidiEvent(new MetaMessage(0x03, data, data.length), 0));
			return t;
		}
		catch (Exception e)
		{
			throw new IllegalStateException(e);
		}
	}

	private static void note(Track t, int channel, double beat, int pitch)
	{
		try
		{
			long on = Math.round(beat * PPQ);
			t.add(new MidiEvent(new ShortMessage(ShortMessage.NOTE_ON, channel, pitch, 90), on));
			t.add(new MidiEvent(new ShortMessage(ShortMessage.NOTE_OFF, channel, pitch, 0), on + PPQ / 4));
		}
		catch (Exception e)
		{
			throw new IllegalStateException(e);
		}
	}

	private static ByteArrayInputStream bytes(Sequence seq) throws Exception
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		MidiSystem.write(seq, 1, out);
		return new ByteArrayInputStream(out.toByteArray());
	}

	private static String labels(Song song)
	{
		List<Step> steps = song.getSteps();
		return steps.stream().map(Step::label).collect(Collectors.joining(" "));
	}
}

package com.clanpiano;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import com.clanpiano.song.Song;
import com.clanpiano.song.SongLibrary;
import com.clanpiano.song.SongParser;
import java.util.EnumSet;
import java.util.List;
import org.junit.Test;

public class SongParserTest
{
	@Test
	public void parsesHeadersNotesRestsDurationsAndChords()
	{
		Song song = SongParser.parse(String.join("\n",
			"title: Test Song",
			"artist: Someone",
			"// a comment line",
			"C4 D#4 | Eb5*3 - // trailing comment",
			"C4+E4+G4 -*2 B5"), "fallback", "test");

		assertEquals("Test Song", song.getTitle());
		assertEquals("Someone", song.getArtist());
		// C4, D#4, Eb5 + 2 holds, rest, chord, 2 rests, B5
		assertEquals(10, song.length());
		assertEquals(5, song.noteCount());
		assertEquals(EnumSet.of(PianoKey.C4), song.getSteps().get(0).getKeys());
		assertEquals(EnumSet.of(PianoKey.DS4), song.getSteps().get(1).getKeys());
		assertEquals(EnumSet.of(PianoKey.DS5), song.getSteps().get(2).getKeys());
		assertTrue(song.getSteps().get(3).isRest());
		assertTrue(song.getSteps().get(5).isRest());
		assertEquals(EnumSet.of(PianoKey.C4, PianoKey.E4, PianoKey.G4), song.getSteps().get(6).getKeys());
		assertEquals(EnumSet.of(PianoKey.B5), song.getSteps().get(9).getKeys());
	}

	@Test
	public void transposeShiftsNotes()
	{
		Song song = SongParser.parse("transpose: 12\nC3 B4", "t", "test");
		assertEquals(PianoKey.C4, song.getSteps().get(0).getKeys().iterator().next());
		assertEquals(PianoKey.B5, song.getSteps().get(1).getKeys().iterator().next());
	}

	@Test
	public void fallbackTitleAndTrailingRestsTrimmed()
	{
		Song song = SongParser.parse("C4 - - -", "My File", "test");
		assertEquals("My File", song.getTitle());
		assertEquals(1, song.length());
	}

	@Test
	public void rejectsNotesOutsideTheKeyboard()
	{
		expectError("C4 B3", "line 1");
		expectError("C6", "outside");
		expectError("H4", "not a note");
		expectError("C4*0", "duration");
		expectError("- -", "no notes");
	}

	@Test
	public void everyBuiltInSongLoads()
	{
		SongLibrary library = new SongLibrary(null);
		library.reload();
		assertEquals("errors: " + library.getErrors(), 0, library.getErrors().size());
		assertTrue(library.getSongs().size() >= 10);
		for (Song song : library.getSongs())
		{
			assertFalse(song.getTitle(), song.getTitle().isEmpty());
			assertTrue(song.getTitle(), song.noteCount() > 8);
		}
	}

	@Test
	public void builtInSongsAreFiledInFolders()
	{
		SongLibrary library = new SongLibrary(null);
		library.reload();
		assertEquals(java.util.Arrays.asList("Classical", "Folk & Shanties", "Holidays & Parties", "Nursery Rhymes"),
			library.getFolders());
		for (Song song : library.getSongs())
		{
			assertTrue(song.getTitle(), library.getFolders().contains(song.getFolder()));
			assertTrue(song.getTitle(), song.duration().matches("[0-9]+:[0-9][0-9]"));
			assertTrue(song.getTitle(), song.lowestKey().ordinal() <= song.highestKey().ordinal());
		}
	}

	@Test
	public void customSubfoldersBecomeFoldersEvenWhenEmpty() throws Exception
	{
		java.nio.file.Path dir = java.nio.file.Files.createTempDirectory("piano-songs");
		java.nio.file.Files.createDirectories(dir.resolve("RuneScape"));
		java.nio.file.Files.createDirectories(dir.resolve("Clan"));
		java.nio.file.Files.write(dir.resolve("Clan").resolve("anthem.txt"), "title: Anthem\nC4 D4 E4".getBytes());
		java.nio.file.Files.write(dir.resolve("loose.txt"), "C4 E4 G4".getBytes());

		SongLibrary library = new SongLibrary(net.runelite.client.util.Filepath.Unchecked.getRooted(dir));
		library.reload();
		List<String> folders = library.getFolders();
		assertEquals(java.util.Arrays.asList(SongLibrary.MY_SONGS, "Clan", "RuneScape"),
			folders.subList(folders.size() - 3, folders.size()));
		assertTrue(library.getCustomFolders().contains("RuneScape"));
		assertEquals(dir.resolve("RuneScape").toString(), library.pathOf("RuneScape").toString());
		Song anthem = library.getSongs().stream().filter(x -> x.getTitle().equals("Anthem")).findFirst().get();
		assertEquals("Clan", anthem.getFolder());
		assertEquals("Clan/Anthem", anthem.id());
	}

	@Test
	public void difficultyGrowsWithBusySongs()
	{
		assertEquals(Song.Difficulty.EASY, SongParser.parse("C4*2 D4*2 E4*2 C4*2", "t", "test").difficulty());
		assertEquals(Song.Difficulty.HARD, SongParser.parse("C4 B5 C#4 A#5 D4 G#5 F#4 B5 C4 A#5", "t", "test").difficulty());
	}

	@Test
	public void keyMappingCoversAllWidgets()
	{
		assertEquals(24, PianoKey.values().length);
		assertEquals(PianoKey.C4, PianoKey.fromMidi(60));
		assertEquals(PianoKey.B5, PianoKey.fromMidi(83));
		long distinct = java.util.Arrays.stream(PianoKey.values()).mapToInt(PianoKey::getWidgetId).distinct().count();
		assertEquals(24, distinct);
		for (PianoKey key : PianoKey.values())
		{
			assertEquals(key, PianoKey.fromWidgetId(key.getWidgetId()));
			assertEquals(key, PianoKey.fromWidgetId(key.getLabelWidgetId()));
		}
	}

	private static void expectError(String body, String fragment)
	{
		try
		{
			SongParser.parse(body, "t", "test");
			fail("expected an error for: " + body);
		}
		catch (IllegalArgumentException e)
		{
			assertTrue(e.getMessage(), e.getMessage().contains(fragment));
		}
	}
}

package com.clanpiano;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.clanpiano.song.Song;
import com.clanpiano.song.SongParser;
import java.util.EnumSet;
import org.junit.Test;

public class SongPlayerTest
{
	private static final Song SONG = SongParser.parse("C4 - E4+G4 D4*2 F4", "t", "test");

	@Test
	public void followModeWaitsForKeysSkipsRestsAndMovesOnAfterAWrongKey()
	{
		SongPlayer p = new SongPlayer();
		p.load(SONG);
		p.start(PlayMode.FOLLOW, 4, false);

		assertEquals(SongPlayer.State.PLAYING, p.getState());
		assertEquals(EnumSet.of(PianoKey.C4), p.remaining());
		p.tick(); // the clock does not move follow mode
		assertEquals(0, p.getPosition());

		assertEquals(SongPlayer.PressResult.WRONG, p.press(PianoKey.D4));
		assertEquals(2, p.getPosition()); // moved on anyway, rest skipped
		assertEquals(SongPlayer.PressResult.PARTIAL, p.press(PianoKey.G4));
		assertEquals(EnumSet.of(PianoKey.E4), p.remaining());
		assertEquals(SongPlayer.PressResult.HIT, p.press(PianoKey.E4));
		assertEquals(SongPlayer.PressResult.HIT, p.press(PianoKey.D4));
		assertEquals(5, p.getPosition()); // D4's hold skipped
		assertEquals(SongPlayer.PressResult.HIT, p.press(PianoKey.F4));

		assertEquals(SongPlayer.State.FINISHED, p.getState());
		assertEquals(3, p.getHits());
		assertEquals(1, p.getWrong());
		assertEquals(1, p.getMisses());
		assertNull(p.current());
	}

	@Test
	public void tempoModeWrongKeyDarkensTheStepUntilTheNextTick()
	{
		SongPlayer p = new SongPlayer();
		p.load(SONG);
		p.start(PlayMode.TEMPO, 0, false);

		assertEquals(SongPlayer.PressResult.WRONG, p.press(PianoKey.D4));
		assertTrue(p.remaining().isEmpty()); // box goes dark, no second try this tick
		assertEquals(SongPlayer.PressResult.WRONG, p.press(PianoKey.C4));
		assertEquals(0, p.getPosition());
		p.tick();
		p.tick();
		assertEquals(EnumSet.of(PianoKey.E4, PianoKey.G4), p.remaining());
		assertEquals(1, p.getMisses());
		assertEquals(2, p.getWrong());
	}

	@Test
	public void playingTheFirstNoteStartsWithoutCountIn()
	{
		SongPlayer p = new SongPlayer();
		p.load(SongParser.parse("- - C4 D4", "t", "test"));
		assertEquals(2, p.firstNoteIndex());
		assertEquals(2, p.dueBase()); // idle: the first note sits on the line

		p.startAtFirstNote(PlayMode.TEMPO, false);
		assertEquals(2, p.getPosition());
		assertEquals(SongPlayer.PressResult.HIT, p.press(PianoKey.C4));
		assertTrue(p.remaining().isEmpty());
		p.tick();
		assertEquals(EnumSet.of(PianoKey.D4), p.remaining());

		p.start(PlayMode.TEMPO, 3, false);
		assertEquals(-3, p.dueBase()); // first step lands after the count-in
	}

	@Test
	public void tempoModeAdvancesEveryTickAndCountsMisses()
	{
		SongPlayer p = new SongPlayer();
		p.load(SONG);
		p.start(PlayMode.TEMPO, 2, false);

		assertEquals(SongPlayer.State.COUNT_IN, p.getState());
		assertEquals("C", p.upcoming(1).get(0).label());
		p.tick();
		p.tick();
		assertEquals(SongPlayer.State.PLAYING, p.getState());

		p.press(PianoKey.C4); // hit, stays on this step until the tick
		assertEquals(0, p.getPosition());
		p.tick(); // -> rest
		p.tick(); // -> chord
		p.press(PianoKey.E4); // only half the chord
		p.tick(); // miss -> D4
		p.tick(); // miss -> hold
		p.tick(); // -> F4
		p.press(PianoKey.F4);
		p.tick();

		assertEquals(SongPlayer.State.FINISHED, p.getState());
		assertEquals(2, p.getHits());
		assertEquals(2, p.getMisses());
	}

	@Test
	public void leadWindowLightsTheNextNoteEarly()
	{
		SongPlayer p = new SongPlayer();
		p.load(SongParser.parse("C4 D4 - E4", "t", "test"));
		p.startAtFirstNote(PlayMode.TEMPO, false, 1);

		assertEquals(EnumSet.of(PianoKey.C4), p.remaining());
		assertEquals(SongPlayer.PressResult.HIT, p.press(PianoKey.C4));
		assertEquals(EnumSet.of(PianoKey.D4), p.remaining()); // one tick early
		assertEquals(SongPlayer.PressResult.HIT, p.press(PianoKey.D4));
		assertTrue(p.remaining().isEmpty()); // E4 is three ticks away
		p.tick();
		p.tick();
		assertEquals(EnumSet.of(PianoKey.E4), p.remaining()); // lit during the rest
		p.tick();
		p.tick(); // E4's own tick passes unplayed
		assertEquals(SongPlayer.State.FINISHED, p.getState());
		assertEquals(2, p.getHits());
		assertEquals(1, p.getMisses());
	}

	@Test
	public void leadWindowOpensDuringTheCountIn()
	{
		SongPlayer p = new SongPlayer();
		p.load(SongParser.parse("C4 D4", "t", "test"));
		p.start(PlayMode.TEMPO, 3, false, 1);
		assertTrue(p.remaining().isEmpty());
		p.tick();
		p.tick();
		assertEquals(EnumSet.of(PianoKey.C4), p.remaining());
		assertEquals(SongPlayer.PressResult.HIT, p.press(PianoKey.C4));
	}

	@Test
	public void loopRestartsFromTheTop()
	{
		SongPlayer p = new SongPlayer();
		p.load(SongParser.parse("C4 D4", "t", "test"));
		p.start(PlayMode.FOLLOW, 0, true);
		p.press(PianoKey.C4);
		p.press(PianoKey.D4);
		assertEquals(SongPlayer.State.PLAYING, p.getState());
		assertEquals(0, p.getPosition());
	}
}

package com.clanpiano.song;

import static org.junit.Assert.assertEquals;

import java.io.ByteArrayOutputStream;
import java.util.List;
import org.junit.Test;

public class MidiFileTest
{
	@Test
	public void readsRunningStatusMetaAndProgramChanges()
	{
		ByteArrayOutputStream track = new ByteArrayOutputStream();
		write(track, 0x00, 0xFF, 0x03, 0x04, 'L', 'e', 'a', 'd'); // track name
		write(track, 0x00, 0xC1, 73);                         // program change: flute, channel 1
		write(track, 0x00, 0x91, 60, 90);                     // note on C4
		write(track, 0x83, 0x60, 62, 90);                     // 480 ticks later, running status: D4
		write(track, 0x00, 60, 0);                            // running status, velocity 0 = off
		write(track, 0x00, 0xF0, 0x02, 0x01, 0xF7);           // sysex, skipped
		write(track, 0x00, 0xFF, 0x2F, 0x00);                 // end of track

		ByteArrayOutputStream file = new ByteArrayOutputStream();
		write(file, 'M', 'T', 'h', 'd', 0, 0, 0, 6, 0, 0, 0, 1, 0x01, 0xE0); // format 0, 1 track, 480 ppq
		write(file, 'M', 'T', 'r', 'k', 0, 0, 0, track.size());
		file.write(track.toByteArray(), 0, track.size());

		MidiFile midi = MidiFile.parse(file.toByteArray());
		assertEquals(480.0, midi.ticksPerBeat, 0);
		List<MidiFile.Event> events = midi.tracks.get(0);
		assertEquals("Lead", events.get(0).metaText());
		assertEquals(MidiFile.PROGRAM_CHANGE, events.get(1).command);
		assertEquals(73, events.get(1).data1);
		assertEquals(1, events.get(2).channel);
		MidiFile.Event d4 = events.get(3);
		assertEquals(480, d4.tick);
		assertEquals(MidiFile.NOTE_ON, d4.command);
		assertEquals(62, d4.data1);
		assertEquals(0, events.get(4).data2);
		assertEquals(6, events.size()); // name, program, 3 notes, end of track
	}

	@Test(expected = IllegalArgumentException.class)
	public void rejectsFilesThatAreNotMidi()
	{
		MidiFile.parse("title: not midi".getBytes());
	}

	private static void write(ByteArrayOutputStream out, int... bytes)
	{
		for (int b : bytes)
		{
			out.write(b);
		}
	}
}

package com.clanpiano.song;

import java.io.BufferedInputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.stream.Collectors;
import javax.sound.midi.MetaMessage;
import javax.sound.midi.MidiEvent;
import javax.sound.midi.MidiMessage;
import javax.sound.midi.MidiSystem;
import javax.sound.midi.Sequence;
import javax.sound.midi.ShortMessage;
import javax.sound.midi.Track;

/** Dev tool: shows how each MIDI in a folder is turned into a piano song. ./gradlew midiReport */
public final class MidiReport
{
	private static double score(List<MidiImporter.Note> notes, int program)
	{
		return MidiImporter.melodyScore(notes) * MidiImporter.programWeight(program);
	}

	public static void main(String[] args) throws Exception
	{
		Path dir = Paths.get(args[0]);
		List<Path> files;
		try (java.util.stream.Stream<Path> s = Files.list(dir))
		{
			files = s.filter(p -> p.toString().toLowerCase().endsWith(".mid")).sorted().collect(Collectors.toList());
		}
		for (Path f : files)
		{
			Sequence seq;
			try (BufferedInputStream in = new BufferedInputStream(Files.newInputStream(f)))
			{
				seq = MidiSystem.getSequence(in);
			}
			System.out.println("== " + f.getFileName() + "  (ppq " + seq.getResolution() + ", " + seq.getTracks().length + " tracks)");
			Map<String, List<MidiImporter.Note>> parts = new TreeMap<>();
			Map<String, Integer> programs = new TreeMap<>();
			Track[] tracks = seq.getTracks();
			for (int t = 0; t < tracks.length; t++)
			{
				for (int i = 0; i < tracks[t].size(); i++)
				{
					MidiEvent e = tracks[t].get(i);
					MidiMessage m = e.getMessage();
					if (!(m instanceof ShortMessage))
					{
						continue;
					}
					ShortMessage sm = (ShortMessage) m;
					String key = t + ":" + sm.getChannel();
					if (sm.getCommand() == ShortMessage.PROGRAM_CHANGE)
					{
						programs.putIfAbsent(key, sm.getData1());
					}
					if (sm.getCommand() == ShortMessage.NOTE_ON && sm.getData2() > 0 && sm.getChannel() != 9)
					{
						parts.computeIfAbsent(key, k -> new ArrayList<>()).add(new MidiImporter.Note(e.getTick(), sm.getData1()));
					}
				}
			}
			parts.entrySet().stream()
				.sorted((a, b) -> Double.compare(score(b.getValue(), programs.getOrDefault(b.getKey(), 0)), score(a.getValue(), programs.getOrDefault(a.getKey(), 0))))
				.limit(0)
				.forEach(e -> System.out.printf("   part %-5s prog %-3s notes %4d  mean pitch %5.1f  score %6.1f%n",
					e.getKey(), programs.getOrDefault(e.getKey(), -1), e.getValue().size(),
					e.getValue().stream().mapToInt(n -> n.pitch).average().orElse(0),
					score(e.getValue(), programs.getOrDefault(e.getKey(), 0))));
			try (BufferedInputStream in = new BufferedInputStream(Files.newInputStream(f)))
			{
				Song main = MidiImporter.load(in, f.getFileName().toString(), f.getFileName().toString());
				for (Song song : main.versions())
				{
					System.out.println("   -> [" + song.getPart() + "] " + song.noteCount() + " notes, " + song.duration()
						+ ", " + song.difficulty() + ", keys " + song.lowestKey().displayName() + " to " + song.highestKey().displayName());
					System.out.println("      " + song.getSteps().stream().limit(40).map(Step::label).collect(Collectors.joining(" ")));
				}
			}
			catch (RuntimeException ex)
			{
				System.out.println("   !! " + ex.getMessage());
			}
		}
	}
}
